-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.announcements_feed(at timestamp with time zone, max_rows integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', x.id, 'kind', x.kind, 'title', x.title, 'body', x.body, 'items', x.items,
           'publishedAt', x.publish_at) order by x.publish_at desc, x.id desc), '[]'::jsonb)
    from (
      select a.* from public.announcements a
       where a.publish_at <= at
         and a.withdrawn_at is null
         and (a.release_id is null
              or exists (select from public.releases r where r.id = a.release_id and r.status = 'published'))
       order by a.publish_at desc, a.id desc
       limit least(greatest(coalesce(max_rows, 100), 1), 200)
    ) x;
$function$;

grant execute on function public.announcements_feed(at timestamp with time zone, max_rows integer) to service_role;
